<h1><?= e(Db::setting('name')) ?> <?= e(t('· CV & portfolio')) ?></h1><p><?= e(t('Only your saved evidence. Print / Save as PDF to export.')) ?></p><?php foreach(['portfolio','placements','thesis']as $kind): ?><section class="card"><h2><?= e(StudyService::catalog()[$kind][0]) ?></h2><?php foreach(StudyService::rows($kind)as $r): ?><dl><?php foreach($r['fields']as $k=>$v): ?><dt><?= e(ucfirst(str_replace('_',' ',$k))) ?></dt><dd><?= nl2br(e($v)) ?></dd><?php endforeach; ?></dl><?php endforeach; ?></section><?php endforeach; ?>
